    function FormField({ id, label, required = false, type = "text", placeholder = "", value = "", hint = "", error = "" }) {
      const describedBy = [hint ? id + "-hint" : "", error ? id + "-error" : ""].filter(Boolean).join(" ");

      return `
        <div class="form-field ${error ? "invalid" : ""}">
          <label for="${id}">
            ${escapeHtml(label)}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${escapeHtml(placeholder)}"
            value="${escapeHtml(value)}"
            ${required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            ${error ? 'aria-invalid="true"' : ""}
          />
          ${hint ? `<p class="field-hint" id="${id}-hint">${escapeHtml(hint)}</p>` : ""}
          ${error ? `<p class="field-error" id="${id}-error">${escapeHtml(error)}</p>` : ""}
        </div>
      `;
    }

