              label: "Full name",
              required: true,
              placeholder: "Jordan Lee",
              value: state.values.fullName,
              error: showErrors ? errors.fullName || "" : ""
            })}
            ${FormField({
              id: "email",
              label: "Email address",
              required: true,
              type: "email",
              placeholder: "jordan@company.com",
              value: state.values.email,
              error: showErrors ? errors.email || "" : ""
            })}
