              error: showErrors ? errors.phone || "" : ""
            })}
            <button class="submit-button" type="submit">Submit request</button>
            ${state.submittedSuccessfully ? '<div class="success-banner" role="status">Thanks! Your support request has been prepared for submission.</div>' : ""}
          </form>
        </section>
      `;
    }

